processing.text:

if @@admin = 0 and @type = '1' begin
	if @@sysDatabaseName.dbo.FastBusiness$System$GetAuthorize(@@admin, @@userID, '[#CONTROLLER#]', 'Edit') = 0 select @type = '0'
end

declare @message nvarchar(4000), @q nvarchar(4000), @duplicate nvarchar(4000)[#Irregular#], @irregular nvarchar(4000), @irregularChars varchar(128)[#Irregular#], @field varchar(32), @r int

[#Irregular#]select @irregularChars = &IrregularValue;
select @irregular = case @@language when 'v' then N'Giá trị tại ô <span class="Highlight">%invalidCell</span> có chứa các ký tự: ' + @irregularChars else 'The value of cell <span class="Highlight">%invalidCell</span> contains any of the following characters: ' + @irregularChars	end[#Irregular#]
select @duplicate = case @@language when 'v' then N'Giá trị tại ô <span class="Highlight">%invalidCell</span> đã có hoặc lồng nhau.' else 'The value of cell <span class="Highlight">%invalidCell</span> is invalid or already exists.' end

create index i on @@table ([#TXTKEY#])

-- Delete
if @type = '0' delete @@table from @@table a join [#TABLE#] b on [#IMPORTKEY#]

-- Checking
&Checking;
[#Irregular#]
if @$mode = 1 begin
	&IrregularMessage;
	&StartErrorCount;
	&InsertErrorTable; select '[#TXTKEY#]', stt, @message from @@table where [#TXTKEY#] like '%[' + @irregularChars + ']%'
	&EndErrorCount;
end else begin
	select @field = '[#TXTKEY#]', @r = min(stt) from @@table where [#TXTKEY#] like '%[' + @irregularChars + ']%'&Irregular;
end[#Irregular#]

-- Gather
select a.* into #k from @@table a join [#TABLE#] b on [#IMPORTKEY#]
delete @@table from @@table a where exists(select 1 from #k b where [#IMPORTKEY#])
[#Irregular#]
-- Checking
select @field = '[#TXTKEY#]'
if @$mode = 1 begin
	&StartErrorCount;
	select @q = '&InsertErrorTable; select @field, a.stt, ''00003'' from @@table a, @@table b with (index(i)) where [#IMPORTKEY_NOT#] and a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + ''%''
		&w1;@field&w2;a.stt&w3;''00003''&w4; group by a.stt'
	exec sp_executesql @q, N'@field varchar(32)', @field
	&EndErrorCount;
	&StartErrorCount;
	select @q = '&InsertErrorTable; select @field, a.stt, ''00003'' from @@table a, [#TABLE#] b where a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + ''%''
		&w1;@field&w2;a.stt&w3;''00003''&w4; group by a.stt'
	exec sp_executesql @q, N'@field varchar(32)', @field
	&EndErrorCount;
	&StartErrorCount;
	select @q = '&InsertErrorTable; select @field, b.stt, ''00003'' from [#TABLE#] a, @@table b with (index(i)) where a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + ''%''
		&w1;@field&w2;b.stt&w3;''00003''&w4; group by b.stt'
	exec sp_executesql @q, N'@field varchar(32)', @field
	&EndErrorCount;
end else begin
	select @q = 'select top 1 @r = a.stt from @@table a, @@table b with (index(i)) where [#IMPORTKEY_NOT#] and a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + ''%'''
	exec sp_executesql @q, N'@r int output', @r = @r output&Duplicate;
	select top 1 @r = a.stt from @@table a, [#TABLE#] b where a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + '%'&Duplicate;
	select @q = 'select top 1 @r = b.stt from [#TABLE#] a, @@table b with (index(i)) where a.[#TXTKEY#] like rtrim(b.[#TXTKEY#]) + ''%'''
	exec sp_executesql @q, N'@r int output', @r = @r output&Duplicate;
end
[#Irregular#]
&EndErrorMode;

-- Insert
&Inserting;

-- Update
if @type = '1' begin &Updating; end
